public final class TokenManager {
 public let client: OAuth2Client
 public let store: TokenStore
 public weak var wipeHandler: SessionWipeHandler?

 private let lock = NSLock()
 private var cached: OAuth2Tokens?
 private var inFlightRefresh: Task<OAuth2Tokens, Error>?
 private var sessionGeneration: UInt64 = 0

 public init(client: OAuth2Client, store: TokenStore, wipeHandler: SessionWipeHandler? = nil) {
 self.client = client
 self.store = store
 self.wipeHandler = wipeHandler
 // Best-effort load on init.
 self.cached = try? store.load()
 }

 /// `true` if we have a refresh token on disk right now. Accessible from
 /// SwiftUI via `AuthViewModel.isSignedIn`.
 public var hasSession: Bool {
 lock.lock(); defer { lock.unlock() }
 return cached != nil
 }

 public func currentAccessToken() throws -> String {
 lock.lock(); defer { lock.unlock() }
 guard let t = cached else { throw TokenManagerError.notSignedIn }
 return t.accessToken
 }

 /// Install freshly-exchanged tokens (from the sign-in view model). Writes
 /// to the store and caches in memory.
 public func install(tokens: OAuth2Tokens) throws {
 lock.lock()
 defer { lock.unlock() }
 do {
 try store.save(tokens)
 } catch let e as TokenStoreError {
 throw TokenManagerError.persistenceFailed(e)
 }
 sessionGeneration &+= 1
 cached = tokens
 }

 /// Refresh the session once. Shared by the 401-retry helper below and
 /// by proactive refresh at app launch. Write-before-return: the new
 /// tokens hit the Keychain before this function resolves.
 @discardableResult
 public func refresh() async throws -> OAuth2Tokens {
 let task = withLock { () -> Task<OAuth2Tokens, Error>? in
 if let existing = inFlightRefresh {
 return existing
 }
 guard let current = cached else {
 return nil
 }
 let task = makeRefreshTask(current: current, generation: sessionGeneration)
 inFlightRefresh = task
 return task
 }

 guard let task else {
 throw TokenManagerError.notSignedIn
 }

 return try await task.value
 }

 private func persistRefreshedTokens(_ tokens: OAuth2Tokens, generation: UInt64) throws -> OAuth2Tokens {
 lock.lock()
 defer { lock.unlock() }
 guard generation == sessionGeneration, cached != nil else {
 throw TokenManagerError.notSignedIn
 }
 do {
 try store.save(tokens)
 } catch let e as TokenStoreError {
 throw TokenManagerError.persistenceFailed(e)
 }
 cached = tokens
 return tokens
 }

 private func clearInflight(ifGeneration generation: UInt64) {
 lock.lock()
 if generation == sessionGeneration {
 inFlightRefresh = nil
 }
 lock.unlock()
 }
...
private func makeRefreshTask(current: OAuth2Tokens, generation: UInt64) -> Task<OAuth2Tokens, Error> {
 Task { [self, client] in
 defer { clearInflight(ifGeneration: generation) }

 do {
 let newTokens: OAuth2Tokens
 do {
 newTokens = try await client.refresh(refreshToken: current.refreshToken)
 } catch let err as OAuth2Error {
 if case .whitelistDenied(let msg) = err {
 throw TokenManagerError.whitelistDenied(msg)
 }
 throw TokenManagerError.refreshFailed(err)
 }

 // WRITE-BEFORE-RETURN. If this throws, the caller treats the
 // user as signed out — see `refreshAndRetry` wiring.
 return try persistRefreshedTokens(newTokens, generation: generation)
 } catch {
 // A refresh failure (expired/rotated/revoked refresh token OR
 // a store write failure) locks the user out. Wipe silently.
 if isGenerationActive(generation) {
 await localSignOut()
 }
 throw error
 }
 }
 }

 /// 401-retry helper. `perform` receives a bearer access token; return
 /// `nil` to indicate a 401 that needs one refresh attempt.
 public func performWithRetry (
 _ perform: (String) async throws -> T?
 ) async throws -> T {
 let token = try currentAccessToken()
 if let first = try await perform(token) {
 return first
 }
 let refreshed = try await refresh()
 guard let second = try await perform(refreshed.accessToken) else {
 throw TokenManagerError.refreshFailed(.unauthorized)
 }
 return second
 }

 /// Full sign-out: wipe Keychain and downstream caches before any network
 /// call, then best-effort revoke the captured server token pair.
 public func signOut() async {
 let snapshot = invalidateLocalSession()
 if let t = snapshot {
 let revokeAll = await client.revokeAll(accessToken: t.accessToken)
 if revokeAll == .unavailable {
 await client.revoke(accessToken: t.accessToken)
 await client.revoke(refreshToken: t.refreshToken)
 }
 }
 }

 /// Wipe everything local. Used by `signOut` and by refresh-failure
 /// lock-outs. Never hits the network.
 public func localSignOut() async {
 _ = invalidateLocalSession()
 }

 private func invalidateLocalSession() -> OAuth2Tokens? {
 let snapshot: OAuth2Tokens?
 let refreshToCancel: Task<OAuth2Tokens, Error>?
 lock.lock()
 snapshot = cached
 sessionGeneration &+= 1
 cached = nil
 refreshToCancel = inFlightRefresh
 inFlightRefresh = nil
 lock.unlock()

 refreshToCancel?.cancel()
 try? store.clear()
 wipeHandler?.wipeAfterSignOut()
 return snapshot
 }
}

The iOS Keychain is the only Apple-sanctioned storage mechanism for OAuth tokens, API keys, passwords, and other credentials. Cybernews found in 2025 that 71% of iOS apps leak at least one hardcoded secret — primarily through `UserDefaults`, `Info.plist`, or `.xcconfig` files that produce plaintext artifacts trivially extractable from device backups or IPA bundles. This reference covers the complete credential lifecycle: secure storage via Keychain Services, OAuth2/OIDC authentication flows, atomic token refresh with rotation, runtime secret fetching, key rotation strategies, and comprehensive logout cleanup.
