export type OAuthDeviceCodePollOptions = {
 intervalSeconds?: number;
 expiresInSeconds?: number;
 waitBeforeFirstPoll?: boolean;
 poll: () => Promise<OAuthDeviceCodePollResult >;
 signal?: AbortSignal;
};
